        ERC20Mock collateralToken = new ERC20Mock("Collateral", "COL", 18);
        ERC20Mock debtToken = new ERC20Mock("Debt", "DEBT", 18);
        // Transfer ownership of c? No, owner is hardcoded in C from constructor
        // But in our test C has no constructor; owner() returns a hardcoded value from Clone.
        // For the reference contract, owner() returns address(0x0) from _getArgAddress(0x0) because no immutable args.
        // For the mutant, owner() returns address(0xdead).
        // We need to work with the deployed c directly.

