// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, ERC20, CoolerFactory} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    CoolerFactory factory;
    ERC20 collateralToken;
    ERC20 debtToken;
    address constant BUGGY_OWNER = address(0xdead);

    function setUp() public {
        factory = new CoolerFactory();
        collateralToken = new ERC20("Collateral", "COL", 18);
        debtToken = new ERC20("Debt", "DEBT", 18);
        // Give this contract some collateral and debt tokens
        collateralToken._mint(address(this), 1000e18);
        debtToken._mint(address(this), 1000e18);
        // Approve factory (though not needed directly)
        // Generate a cooler for this contract (owner = address(this))
        vm.prank(address(this));
        address coolerAddr = factory.generateCooler(collateralToken, debtToken);
        c = C(payable(coolerAddr));
    }

    function testRegression_property() public {
        // Arrange: owner of c is address(this)
        // Request a loan
        uint256 amount = 1000e18;
        uint256 interest = 1e17; // 10%
        uint256 ltc = 2e18; // 2x
        uint256 duration = 30 days;
        uint256 collateralNeeded = c.collateralFor(amount, ltc);

        // Approve collateral transfer
        collateralToken.approve(address(c), collateralNeeded);
        vm.prank(address(this));
        uint256 reqID = c.requestLoan(amount, interest, ltc, duration);

        // Now clear the request (as lender, another account)
        address lender = address(0x1234);
        // Give lender enough debt tokens
        debtToken._mint(lender, amount);
        vm.prank(lender);
        debtToken.approve(address(c), amount);

        // Lender clears request, repayDirect=true
        vm.prank(lender);
        uint256 loanID = c.clearRequest(reqID, true, false);

        // Act: check the debt balance of the hardcoded buggy owner address
        // In reference, debt was sent to owner() == address(this), so BUGGY_OWNER balance is 0
        // In bug, debt was sent to BUGGY_OWNER, so balance > 0
        uint256 balanceBuggy = debtToken.balanceOf(BUGGY_OWNER);

        // Assert: reference should have 0 debt at BUGGY_OWNER
        assertTrue(balanceBuggy == 0, "Buggy owner should not have debt in reference");
    }
}

